import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'
    my_last, opp_last = history[-1]
    my_prev, opp_prev = history[-2]

    if n < 8:
        if opp_last == 'D':
            return 'D'
        return 'C'

    opp_defects = sum(1 for _, o in history if o == 'D')
    recent = history[-12:]
    recent_opp_defects = sum(1 for _, o in recent if o == 'D')
    last_opp_defects = sum(1 for _, o in history[-4:] if o == 'D')

    if opp_defects <= 2:
        return 'C'

    if recent_opp_defects >= 8:
        return 'D'

    if n >= 20:
        early = history[:n//2]
        late = history[n//2:]
        early_rate = sum(1 for _, o in early if o == 'D') / max(1, len(early))
        late_rate = sum(1 for _, o in late if o == 'D') / max(1, len(late))
        if late_rate > early_rate + 0.15 and recent_opp_defects >= 5:
            return 'D'

    if opp_last == 'D' and opp_prev == 'C' and my_last == 'C':
        if rng.random() < 0.75:
            return 'D'
        return 'C'

    if opp_last == 'D':
        if recent_opp_defects >= 4:
            return 'D'
        if rng.random() < 0.45:
            return 'D'
        return 'C'

    if my_last == 'D' and opp_last == 'C':
        if rng.random() < 0.85:
            return 'C'
        return 'D'

    if n > 70 and opp_defects <= 4:
        return 'C'

    if recent_opp_defects == 0:
        if my_last == 'D' and rng.random() < 0.6:
            return 'D'
        return 'C'

    if opp_defects * 3 > n:
        return 'D'

    return 'C'

