    # Classic suspicious Tit-for-Tat with a small forgiveness rule.
    if last_op == 'D':
        # Forgive occasional isolated defections late-ish, otherwise retaliate.
        if n >= 20 and n % 7 == 0 and last2_op == 'C':
            return 'C'
        return 'D'

    # Against persistent cooperation, cooperate.
    if all(a == 'C' for a in op[-8:]):
        return 'C'

    # If opponent alternates C,D suspiciously, defect.
    if len(op) >= 4:
        alt = True
        for i in range(1, min(4, len(op))):
            if op[-i] == op[-i-1]:
                alt = False
                break
        if alt:
            return 'D'

    return 'C'

