def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    def op_run_len():
        if not op:
            return 0
        last = op[-1]
        k = 0
        for a in reversed(op):
            if a == last:
                k += 1
            else:
                break
        return k

    recent = op[-8:]
    op_c = recent.count('C')
    total_op_c = op.count('C')
    total_my_c = my.count('C')

    # Always defect against extremely cooperative or extremely defective records late.
    if n >= 15:
        if total_op_c >= n - 2:
            return 'D'
        if total_op_c <= 2:
            return 'D'

    # If opponent is in a long defect streak, defect back.
    rl = op_run_len()
    if op[-1] == 'D' and rl >= 2:
        return 'D'

    # If opponent just switched away from a defect streak and is now cooperating, forgive sometimes.
    if op[-1] == 'C' and rl >= 2:
        if rng.random() < 0.7:
            return 'C'
        return 'D'

    # Late game: exploit a highly cooperative opponent.
    if n >= 80:
        if op_c >= 7 and op[-1] == 'C':
            return 'D'
        if op_c >= 5 and rng.random() < 0.6:
            return 'D'

    # Mid/late: tendency to defect if opponent's recent cooperation is high.
    if n >= 40:
        if op_c >= 7:
            return 'D' if rng.random() < 0.75 else 'C'
        if op_c <= 2:
            return 'D'

    # Opening: cooperate, then be nice and retaliatory.
    if n <= 3:
        return 'C'

    # Reciprocate the last action most of the time.
    if op[-1] == 'D':
        if rng.random() < 0.8:
            return 'D'
        return 'C'

    # Opponent cooperated: mostly cooperate, but occasionally test/exploit.
    if op_c >= 6 and n >= 10:
        if rng.random() < 0.25:
            return 'D'
    if op_c >= 4 and n >= 20:
        if rng.random() < 0.12:
            return 'D'

    # Avoid being overly predictable.
    if total_my_c == n and n >= 10:
        if rng.random() < 0.15:
            return 'D'

    return 'C'

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    # Identify if the opponent is mostly cooperative or defecting
    coop_count = sum(1 for own, opp in history if opp == 'C')
    defect_count = n - coop_count

    # Estimate opponent's recent behavior
    recent_len = min(10, n)
    recent = history[-recent_len:]
    recent_coop = sum(1 for own, opp in recent if opp == 'C')
    recent_defect = recent_len - recent_coop

    # If opponent is mostly cooperative, cooperate
    if coop_count >= defect_count:
        # But if opponent just defected, retaliate briefly
        if history[-1][1] == 'D':
            # Tit-for-tat: defect once, then return to cooperation if they cooperate
            if n >= 2 and history[-2][1] == 'C':
                return 'D'
            # If they defected multiple times in a row, defect more
            consecutive_defects = 0
            for i in range(n-1, -1, -1):
                if history[i][1] == 'D':
                    consecutive_defects += 1
                else:
                    break
            if consecutive_defects >= 2:
                return 'D'
            return 'D'
        return 'C'

    # Opponent is mostly defecting - defect to minimize losses
    # But occasionally try to re-establish cooperation
    if recent_defect == recent_len:
        # Opponent always defects - maybe try to break cycle
        if n % 20 == 0:
            return 'C'
        return 'D'

    # Mixed strategy - defect more often
    if rng.random() < 0.2:
        return 'C'
    return 'D'
